/**
 * Invitation acceptance logic (S3, F6, F13). Pure functions with no database and no clock of their
 * own, so the invite-user Edge Function and the tests share one decision.
 *
 * Laws that shape this file:
 *   - L1: no randomness and no AI. The token is generated by the database; this module only decides
 *     whether a presented token is acceptable, from the invitation row and the current time.
 *   - F5: the token is never logged, echoed or stored in the clear. The database keeps only a hash.
 */

export type InviteKind = 'member' | 'external_auditor';

export interface InvitationRow {
  id: string;
  org_id: string;
  email: string;
  role_slug: string | null;
  kind: InviteKind;
  expires_at: string | null;
  accepted_at: string | null;
  revoked_at: string | null;
}

export type InviteRejection =
  | 'token_required'
  | 'not_found'
  | 'already_used'
  | 'revoked'
  | 'expired'
  | 'no_role';

export type InviteDecision =
  | { ok: true; invitation: InvitationRow }
  | { ok: false; reason: InviteRejection; message: string };

/** The plain-language message for each rejection, shown verbatim by the acceptance screen. */
export const REJECTION_MESSAGES: Record<InviteRejection, string> = {
  token_required: 'This link is missing its invitation code. Ask for a new invitation.',
  not_found: 'This invitation link is not recognised. It may belong to another platform.',
  already_used: 'This invitation has already been used. Sign in, or ask for a new invitation.',
  revoked: 'This invitation was cancelled. Ask an administrator for a new one.',
  expired: 'This invitation has expired. Ask an administrator for a new one.',
  no_role: 'The role this invitation grants no longer exists. Ask an administrator to re-invite you.',
};

export function rejection(reason: InviteRejection): InviteDecision {
  return { ok: false, reason, message: REJECTION_MESSAGES[reason] };
}

/**
 * Whether a token may be accepted right now. Deterministic: the same row and time always give the
 * same answer. A token with no matching row is 'not_found', never a silent success.
 */
export function evaluateInvitation(
  token: string | null | undefined,
  invitation: InvitationRow | null,
  now: Date
): InviteDecision {
  if (!token || token.trim() === '') return rejection('token_required');
  if (!invitation) return rejection('not_found');
  if (invitation.revoked_at) return rejection('revoked');
  if (invitation.accepted_at) return rejection('already_used');
  if (invitation.expires_at && new Date(invitation.expires_at).getTime() < now.getTime()) {
    return rejection('expired');
  }
  if (invitation.kind === 'member' && !invitation.role_slug) return rejection('no_role');
  return { ok: true, invitation };
}

/**
 * The route an accepted invitation lands on. External auditors go to their portal (F13); members go
 * to the workspace. Kept here so the email link, the Edge Function and the screen agree.
 */
export function acceptanceRoute(kind: InviteKind): string {
  return kind === 'external_auditor' ? '/external' : '/';
}

/** The acceptance link placed in the invitation email. The token is the only variable part. */
export function acceptanceLink(appBaseUrl: string, token: string): string {
  const base = appBaseUrl.replace(/\/+$/, '');
  return `${base}/invite/accept?token=${encodeURIComponent(token)}`;
}
